export type Device = "desktop" | "tablet" | "mobile";

export type DemoEntry = {
  id: string;
  slug: string;
  name: string;
  nameTh?: string;
  industry: string;
  audience: string;
  goal: string;
  theme: string;
  summary: string;
  features: string[];
  routes: { th?: string; en: string };
  /** A few swatches from the demo's own palette, shown on the showcase. */
  palette: string[];
  status: "In progress" | "Review" | "Complete";
};

/** Screenshots are generated by `npm run screenshots` into public/showcase/<slug>/. */
export const screenshotPath = (slug: string, device: Device) => `/showcase/${slug}/${device}.jpg`;

export const deviceSizes: Record<Device, { width: number; height: number; label: string }> = {
  desktop: { width: 1440, height: 900, label: "Desktop · 1440 px" },
  tablet: { width: 820, height: 1180, label: "iPad · 820 px" },
  mobile: { width: 390, height: 844, label: "Mobile · 390 px" },
};
